const DB='WalkMemory';const VER=3;const SETTINGS_KEY='walkMemoryFinalSettings';
let db,map,routeLayer,partnerRouteLayer,landmarkLayer,partnerLandmarkLayer,photoLayer,partnerPhotoLayer,meMarker,liveLine,walkModalMap,walkModalLayer;
let watchId=null,nativeWatchId=null,timer=null,startAt=0,meters=0,points=[],lastPoint=null,currentWalkUid=null;
let editingLandmarkId=null,editingPhotos=[],settings=loadSettings(),account=null,partner=null,partnerSnapshot=null,syncTimer=null,lastKnownLocation=null;
let currentActivityType='walk',currentSlopePercent=null,currentElevation=null,etaProfile={baseSpeed:1.4,routeFactor:1.25,timeSpeeds:{},distanceSpeeds:{},hilliness:0,sampleCount:0},slopeHistory=[],joinedPartnerActivity=null,sharedHostActive=false,sharedPollTimer=null,photoBusy=false;

const $=id=>document.getElementById(id);const now=()=>Date.now();const uid=()=>crypto.randomUUID?crypto.randomUUID():`${Date.now()}-${Math.random().toString(36).slice(2)}`;
function loadSettings(){try{return JSON.parse(localStorage.getItem(SETTINGS_KEY))||{}}catch{return{}}}function saveSettings(){localStorage.setItem(SETTINGS_KEY,JSON.stringify(settings))}
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function safeImageSrc(v){const s=String(v||'');return /^data:image\//i.test(s)||/^https?:\/\//i.test(s)?s.replace(/"/g,'&quot;'):''}
function ft(ms){let s=Math.max(0,Math.floor(ms/1000)),h=Math.floor(s/3600);s%=3600;const m=Math.floor(s/60);s%=60;return[h,m,s].map(x=>String(x).padStart(2,'0')).join(':')}
function mi(m){return(Number(m||0)/1609.344).toFixed(2)}function formatDate(ts){return ts?new Date(ts).toLocaleString():'Unknown date'}
function dist(a,b){const R=6371000,p=Math.PI/180,d1=(b.lat-a.lat)*p,d2=(b.lon-a.lon)*p,q=Math.sin(d1/2)**2+Math.cos(a.lat*p)*Math.cos(b.lat*p)*Math.sin(d2/2)**2;return 2*R*Math.asin(Math.sqrt(q))}
function starText(r){const n=Math.max(0,Math.min(5,Number(r||0)));return n?'★★★★★'.slice(0,n)+'☆☆☆☆☆'.slice(0,5-n):'Not rated'}
function safeColor(v,fallback='#d00000'){const s=String(v||'');return /^#[0-9a-f]{6}$/i.test(s)?s:fallback}
function walkEstimateDataLegacy(l){if(!lastKnownLocation)return null;const direct=dist(lastKnownLocation,l);const estimatedMeters=direct*1.25;const mins=Math.max(1,Math.round(estimatedMeters/1.4/60));return{meters:estimatedMeters,miles:estimatedMeters/1609.344,mins,text:`~${mins} min · ${mi(estimatedMeters)} mi from you`}}
function walkEstimate(l){return walkEstimateData(l)?.text||''}

function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open(DB,VER);r.onupgradeneeded=()=>{const d=r.result;['walks','landmarks','visits','photos'].forEach(s=>{if(!d.objectStoreNames.contains(s))d.createObjectStore(s,{keyPath:'id',autoIncrement:true})})};r.onsuccess=()=>{db=r.result;resolve()};r.onerror=()=>reject(r.error)})}
const store=(n,m='readonly')=>db.transaction(n,m).objectStore(n);const all=n=>new Promise((a,b)=>{const r=store(n).getAll();r.onsuccess=()=>a(r.result);r.onerror=()=>b(r.error)});const get=(n,id)=>new Promise((a,b)=>{const r=store(n).get(id);r.onsuccess=()=>a(r.result);r.onerror=()=>b(r.error)});const put=(n,v)=>new Promise((a,b)=>{const r=store(n,'readwrite').put(v);r.onsuccess=()=>a(r.result);r.onerror=()=>b(r.error)});const remove=(n,id)=>new Promise((a,b)=>{const r=store(n,'readwrite').delete(id);r.onsuccess=()=>a();r.onerror=()=>b(r.error)});const clearStore=n=>new Promise((a,b)=>{const r=store(n,'readwrite').clear();r.onsuccess=()=>a();r.onerror=()=>b(r.error)});

async function migrateData(){const walks=await all('walks'),landmarks=await all('landmarks'),wm=new Map(),lm=new Map();for(const w of walks){let d=false;if(!w.uid){w.uid=uid();d=true}if(!w.updatedAt){w.updatedAt=w.date||now();d=true}if(!Array.isArray(w.points)){w.points=[];d=true}wm.set(w.id,w.uid);if(d)await put('walks',w)}for(const l of landmarks){let d=false;if(!l.uid){l.uid=uid();d=true}if(!l.updatedAt){l.updatedAt=now();d=true}if(!Array.isArray(l.photos)){l.photos=l.photo?[l.photo]:[];d=true}if(!l.photo&&l.photos[0]){l.photo=l.photos[0];d=true}if(l.category==null){l.category='Other';d=true}if(l.subcategory==null){l.subcategory='';d=true}if(l.rating==null){l.rating=0;d=true}if(l.notes==null){l.notes='';d=true}lm.set(l.id,l.uid);if(d)await put('landmarks',l)}for(const v of await all('visits')){let d=false;if(!v.uid){v.uid=uid();d=true}if(!v.landmarkUid&&v.landmarkId!=null&&lm.has(v.landmarkId)){v.landmarkUid=lm.get(v.landmarkId);d=true}if(!v.walkUid&&v.walkId!=null&&wm.has(v.walkId)){v.walkUid=wm.get(v.walkId);d=true}if(!v.updatedAt){v.updatedAt=v.date||now();d=true}if(d)await put('visits',v)}}
async function localSnapshotLegacy(){return{version:4,walks:await all('walks'),landmarks:await all('landmarks'),visits:await all('visits')}}
async function mergeSnapshotLegacy(snap){if(!snap)return;for(const name of ['walks','landmarks','visits'])for(const original of snap[name]||[]){const x={...original};delete x.id;if(!x.uid)x.uid=uid();const existing=(await all(name)).find(y=>y.uid===x.uid);if(existing)x.id=existing.id;await put(name,x)}await migrateData()}

async function initMap(){map=L.map('mapbox').setView([42.59,-72.60],13);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap contributors',maxZoom:19}).addTo(map);routeLayer=L.layerGroup().addTo(map);partnerRouteLayer=L.layerGroup().addTo(map);landmarkLayer=L.layerGroup().addTo(map);partnerLandmarkLayer=L.layerGroup().addTo(map);photoLayer=L.layerGroup().addTo(map);partnerPhotoLayer=L.layerGroup().addTo(map);if($('mapOwner'))$('mapOwner').value=settings.defaultMapOwner||'mine';await renderMap()}
function landmarkMarker(l,isPartner=false){const src=safeImageSrc(l.photo||(l.photos||[])[0]),color=isPartner?safeColor(partner?.walkColor,'#777777'):safeColor(account?.walkColor,'#d00000');const html=src?`<img src="${src}" style="width:40px;height:40px;border-radius:4px;object-fit:cover;border:2px solid ${color};box-shadow:0 2px 8px #0008">`:`<div style="font-size:27px;color:${color}">★</div>`;return L.divIcon({html,className:'',iconSize:[44,44],iconAnchor:[22,22]})}
async function renderMap(){if(!map)return;[routeLayer,partnerRouteLayer,landmarkLayer,partnerLandmarkLayer,photoLayer,partnerPhotoLayer].filter(Boolean).forEach(x=>x.clearLayers());const mine=await localSnapshot(),mode=$('mapOwner')?.value||'mine',myColor=safeColor(account?.walkColor,'#d00000'),partnerColor=safeColor(partner?.walkColor,'#777777');const popup=(l,ownerName='')=>{const eta=walkEstimate(l),cat=[l.category||'Other',l.subcategory].filter(Boolean).join(' › ');return `<b>${esc(l.name)}</b><br>${ownerName?esc(ownerName)+' · ':''}${esc(cat)} · ${esc(starText(l.rating))}${eta?`<br><b>${esc(eta)}</b>`:'<br><span class="muted">Update location to see walk time</span>'}${l.desc?`<br>${esc(l.desc)}`:''}${l.notes?`<br><small>Note: ${esc(l.notes)}</small>`:''}`};const photoIcon=()=>L.divIcon({html:'<div class="photo-map-marker">📷</div>',className:'',iconSize:[30,30],iconAnchor:[15,15]});if(mode!=='partner'){for(const w of mine.walks||[])if((w.points||[]).length>1)L.polyline(w.points.map(p=>[p.lat,p.lon]),{weight:4,opacity:.86,color:myColor}).bindTooltip(esc(w.title||'Activity')).addTo(routeLayer);for(const l of mine.landmarks||[])L.marker([l.lat,l.lon],{icon:landmarkMarker(l)}).bindPopup(popup(l)).addTo(landmarkLayer);if(settings.showPhotoMarkers!==false)for(const ph of mine.photos||[])if(Number.isFinite(+ph.lat)&&Number.isFinite(+ph.lon))L.marker([+ph.lat,+ph.lon],{icon:photoIcon()}).bindPopup(`<b>Activity photo</b><br><img src="${safeImageSrc(ph.image)}" style="width:180px;max-width:100%;border:2px solid #555"><br>${esc(formatDate(ph.date))}`).addTo(photoLayer)}if(mode!=='mine'&&partnerSnapshot){for(const w of partnerSnapshot.walks||[])if((w.points||[]).length>1)L.polyline(w.points.map(p=>[p.lat,p.lon]),{weight:4,opacity:.78,color:partnerColor,dashArray:'7 5'}).bindTooltip(`${esc(partner?.displayName||'Partner')}: ${esc(w.title||'Activity')}`).addTo(partnerRouteLayer);for(const l of partnerSnapshot.landmarks||[])L.marker([l.lat,l.lon],{icon:landmarkMarker(l,true)}).bindPopup(popup(l,partner?.displayName||'Partner')).addTo(partnerLandmarkLayer);if(settings.showPhotoMarkers!==false)for(const ph of partnerSnapshot.photos||[])if(Number.isFinite(+ph.lat)&&Number.isFinite(+ph.lon))L.marker([+ph.lat,+ph.lon],{icon:photoIcon()}).bindPopup(`<b>${esc(partner?.displayName||'Partner')} photo</b><br><img src="${safeImageSrc(ph.image)}" style="width:180px;max-width:100%;border:2px solid #555"><br>${esc(formatDate(ph.date))}`).addTo(partnerPhotoLayer)}}
function tickLegacy(){const d=startAt?now()-startAt:0;$('duration').textContent=ft(d);$('distance').textContent=`${mi(meters)} mi`;$('pace').textContent=meters>0?`${((d/60000)/(meters/1609.344)).toFixed(1)} min/mi`:'—'}
function renderLive(){if(!lastPoint||!map)return;if(!meMarker)meMarker=L.circleMarker([lastPoint.lat,lastPoint.lon],{radius:7,color:safeColor(account?.walkColor,'#ff0000')}).addTo(map);meMarker.setLatLng([lastPoint.lat,lastPoint.lon]);if(liveLine)map.removeLayer(liveLine);if(points.length>1)liveLine=L.polyline(points.map(p=>[p.lat,p.lon]),{weight:5,color:safeColor(account?.walkColor,'#ff0000')}).addTo(map);if(settings.autoCenterTracking)map.panTo([lastPoint.lat,lastPoint.lon],{animate:false})}
async function checkLandmarks(p,walkUid){const ls=await all('landmarks'),vs=await all('visits');for(const l of ls)if(dist(p,l)<=Number(l.radius||50)){const recent=vs.some(v=>v.landmarkUid===l.uid&&now()-Number(v.date||0)<3600000);if(!recent)await put('visits',{uid:uid(),landmarkUid:l.uid,walkUid,date:now(),updatedAt:now()})}}
async function acceptPositionLegacy(coords,timestamp=now()){const accuracy=Number(coords.accuracy??9999);$('gpsDetail').textContent=Number.isFinite(accuracy)?`GPS accuracy: ±${Math.round(accuracy)} m`:'GPS active';if(accuracy>80){$('state').textContent=`WAITING FOR BETTER GPS ±${Math.round(accuracy)}m`;return}const p={lat:Number(coords.latitude),lon:Number(coords.longitude),t:Number(timestamp||now()),accuracy,altitude:coords.altitude==null?null:Number(coords.altitude),speed:coords.speed==null?null:Number(coords.speed)};if(!Number.isFinite(p.lat)||!Number.isFinite(p.lon))return;lastKnownLocation={lat:p.lat,lon:p.lon};if(lastPoint){const d=dist(lastPoint,p),sec=Math.max(.001,(p.t-lastPoint.t)/1000),speed=d/sec,minMove=Math.max(2,Math.min(8,(accuracy+Number(lastPoint.accuracy||accuracy))*.06));if(d<minMove)return;if(speed>12&&(p.speed==null||p.speed>12))return;meters+=d}points.push(p);lastPoint=p;$('state').textContent='TRACKING GPS';renderLive();tick();await checkLandmarks(p,currentWalkUid)}
function nativeBridgeAvailable(){try{return!!(window.WalkMemoryNative?.isAvailable?.())}catch{return false}}
async function startTrackingLegacy(){meters=0;points=[];lastPoint=null;startAt=now();currentWalkUid=uid();$('start').disabled=true;$('stop').disabled=false;$('state').textContent='STARTING GPS';timer=setInterval(tick,1000);if(nativeBridgeAvailable()){try{$('backgroundNote').textContent='Native background GPS active. Keep location set to Allow all the time, battery Unrestricted, and Remove permissions if unused turned off.';$('backgroundNote').classList.remove('hidden');nativeWatchId=await window.WalkMemoryNative.start(loc=>acceptPosition({latitude:loc.latitude,longitude:loc.longitude,accuracy:loc.accuracy,altitude:loc.altitude,speed:loc.speed},loc.time),err=>{$('state').textContent=`GPS ERROR: ${err?.message||err}`});return}catch{$('backgroundNote').textContent='Native GPS failed; falling back to browser GPS.';$('backgroundNote').classList.remove('hidden')}}if(!navigator.geolocation){resetTrackingUI();return alert('GPS unavailable.')}watchId=navigator.geolocation.watchPosition(p=>acceptPosition(p.coords,p.timestamp),e=>{$('state').textContent=`GPS: ${e.message}`},{enableHighAccuracy:true,maximumAge:0,timeout:20000})}
async function stopTrackingLegacy(){if(watchId!==null){navigator.geolocation.clearWatch(watchId);watchId=null}if(nativeWatchId!==null&&window.WalkMemoryNative?.stop){try{await window.WalkMemoryNative.stop(nativeWatchId)}catch{}nativeWatchId=null}clearInterval(timer);timer=null;if(points.length<2){resetTrackingUI();return alert('Not enough accurate GPS points to save this walk.')}const title=prompt('Name this walk:',`Walk ${new Date(startAt).toLocaleDateString()}`)||'Walk';await put('walks',{uid:currentWalkUid,date:startAt,duration:now()-startAt,distance:meters,title,points:[...points],updatedAt:now()});$('state').textContent='SAVED';resetTrackingUI();await refreshAll();scheduleCloudSync()}
function resetTrackingUILegacy(){$('start').disabled=false;$('stop').disabled=true;$('distance').textContent='0.00 mi';$('duration').textContent='00:00:00';$('pace').textContent='—';points=[];lastPoint=null;meters=0;startAt=0;currentWalkUid=null;if(liveLine&&map){map.removeLayer(liveLine);liveLine=null}}
async function locateMeLegacy(refresh=false){if(!navigator.geolocation)return alert('GPS unavailable.');navigator.geolocation.getCurrentPosition(p=>{lastKnownLocation={lat:p.coords.latitude,lon:p.coords.longitude};map?.setView([p.coords.latitude,p.coords.longitude],16);renderMap();if(refresh)renderLists()},e=>alert(e.message),{enableHighAccuracy:true,maximumAge:0,timeout:15000})}

function closeModal(id){$(id).classList.add('hidden')}async function openNewLandmark(){const open=(lat,lon)=>openLandmarkEditor({lat,lon,name:'',desc:'',notes:'',rating:0,category:'Other',radius:50,photos:[]},null);if(lastKnownLocation)return open(lastKnownLocation.lat,lastKnownLocation.lon);if(!navigator.geolocation)return alert('Use Locate Me first.');navigator.geolocation.getCurrentPosition(p=>{lastKnownLocation={lat:p.coords.latitude,lon:p.coords.longitude};open(p.coords.latitude,p.coords.longitude)},e=>alert(e.message),{enableHighAccuracy:true,maximumAge:0,timeout:12000})}
async function openLandmarkById(id){const l=await get('landmarks',Number(id));if(l)openLandmarkEditor(l,l.id)}
function openLandmarkEditor(l,id){editingLandmarkId=id;editingPhotos=[...(l.photos||(l.photo?[l.photo]:[]))];$('lmTitle').textContent=id?'Edit landmark':'Add landmark';$('lmName').value=l.name||'';$('lmCategory').value=l.category||'Other';$('lmSubcategory').value=l.subcategory||'';$('lmRating').value=String(l.rating||0);$('lmDesc').value=l.desc||'';$('lmNotes').value=l.notes||'';$('lmRadius').value=String(l.radius||50);$('lmLat').value=l.lat;$('lmLon').value=l.lon;$('lmId').value=id||'';$('lmPhotos').value='';$('deleteLandmark').classList.toggle('hidden',!id);renderPhotoGallery();$('landmarkModal').classList.remove('hidden')}
function renderPhotoGallery(){$('photoGallery').innerHTML=editingPhotos.length?editingPhotos.map((src,i)=>`<div class="photo-item"><img src="${safeImageSrc(src)}"><button type="button" data-photo-remove="${i}">×</button></div>`).join(''):'<div class="muted">No photos yet.</div>';document.querySelectorAll('[data-photo-remove]').forEach(b=>b.onclick=()=>{editingPhotos.splice(Number(b.dataset.photoRemove),1);renderPhotoGallery()})}
function compressImageSource(src,max=1440,quality=.78){return new Promise((resolve,reject)=>{const img=new Image();img.onerror=()=>reject(new Error('Could not decode photo.'));img.onload=()=>{try{const scale=Math.min(1,max/Math.max(img.width||1,img.height||1)),c=document.createElement('canvas');c.width=Math.max(1,Math.round(img.width*scale));c.height=Math.max(1,Math.round(img.height*scale));const ctx=c.getContext('2d',{alpha:false});ctx.drawImage(img,0,0,c.width,c.height);resolve(c.toDataURL('image/jpeg',quality))}catch(e){reject(e)}};img.src=src})}
function readPhoto(file){return new Promise((resolve,reject)=>{const fr=new FileReader();fr.onerror=()=>reject(fr.error||new Error('Could not read photo.'));fr.onload=async()=>{try{resolve(await compressImageSource(fr.result))}catch(e){reject(e)}};fr.readAsDataURL(file)})}
async function normalizeNativePhoto(data){if(!data)return null;const src=typeof data==='string'?data:data.dataUrl;if(!src)return null;return compressImageSource(src)}
function nativeCameraAvailable(){try{return !!window.WalkMemoryNative?.cameraAvailable?.()}catch{return false}}
async function addLandmarkPhotoFromNative(source='camera'){if(photoBusy)return;photoBusy=true;try{const raw=source==='gallery'?await window.WalkMemoryNative.choosePhoto():await window.WalkMemoryNative.takePhoto();const data=await normalizeNativePhoto(raw);if(data){editingPhotos.push(data);renderPhotoGallery()}}catch(e){if(!/cancel/i.test(String(e?.message||e)))alert(`Camera: ${e?.message||e}`)}finally{photoBusy=false}}
async function addSelectedPhotos(e){const input=e?.target||$('lmPhotos');for(const f of [...(input?.files||[])])if(f.type.startsWith('image/'))try{editingPhotos.push(await readPhoto(f))}catch(err){console.warn(err)}if(input)input.value='';renderPhotoGallery()}
async function saveLandmark(e){e.preventDefault();const existing=editingLandmarkId?await get('landmarks',editingLandmarkId):null,record={...(existing||{}),uid:existing?.uid||uid(),name:$('lmName').value.trim(),category:$('lmCategory').value.trim()||'Other',subcategory:$('lmSubcategory').value.trim(),rating:Number($('lmRating').value),desc:$('lmDesc').value.trim(),notes:$('lmNotes').value.trim(),radius:Number($('lmRadius').value),lat:Number($('lmLat').value),lon:Number($('lmLon').value),photos:[...editingPhotos],photo:editingPhotos[0]||'',updatedAt:now()};if(editingLandmarkId)record.id=editingLandmarkId;await put('landmarks',record);closeModal('landmarkModal');await refreshAll();scheduleCloudSync()}
async function deleteCurrentLandmark(){if(!editingLandmarkId)return;const l=await get('landmarks',editingLandmarkId);if(!l||!confirm(`Delete “${l.name}” and its visit history?`))return;await remove('landmarks',editingLandmarkId);for(const v of await all('visits'))if(v.landmarkUid===l.uid||v.landmarkId===l.id)await remove('visits',v.id);closeModal('landmarkModal');await refreshAll();scheduleCloudSync()}

function categoryOptions(data){const cats=[...new Set((data.landmarks||[]).map(l=>l.category||'Other'))].sort(),cur=$('categoryFilter').value;$('categoryFilter').innerHTML='<option value="">All categories</option>'+cats.map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('');$('categoryFilter').value=cats.includes(cur)?cur:'';subcategoryOptions(data)}
function subcategoryOptions(data){const cat=$('categoryFilter').value,subs=[...new Set((data.landmarks||[]).filter(l=>!cat||(l.category||'Other')===cat).map(l=>l.subcategory||'').filter(Boolean))].sort(),cur=$('subcategoryFilter').value;$('subcategoryFilter').innerHTML='<option value="">All subcategories</option>'+subs.map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('');$('subcategoryFilter').value=subs.includes(cur)?cur:''}
function landmarkCard(l,visits,isPartner=false){const src=safeImageSrc(l.photo||(l.photos||[])[0]),media=src?`<img src="${src}">`:'<div class="placeholder">★</div>',count=visits.filter(v=>v.landmarkUid===l.uid||(v.landmarkId!=null&&v.landmarkId===l.id)).length,eta=walkEstimate(l),click=isPartner?'':` data-landmark-id="${l.id}"`,sub=l.subcategory?`<span class="subchip">${esc(l.subcategory)}</span>`:'';return `<div class="window-card landmark ${isPartner?'':'clickable'}"${click}>${media}<div><div class="landmark-title">${esc(l.name)} <span class="chip">${esc(l.category||'Other')}</span>${sub}${isPartner?`<span class="partner-tag">${esc(partner?.displayName||'PARTNER')}</span>`:''}</div><div class="stars">${esc(starText(l.rating))}</div>${l.desc?`<div>${esc(l.desc)}</div>`:''}${l.notes?`<div class="muted">Note: ${esc(l.notes)}</div>`:''}<small>${count} visits · ${Number(l.radius||50)} m radius · ${(l.photos||[]).length} photos</small>${eta?`<div class="eta">${eta}</div>`:''}</div></div>`}
function passesDistance(l){const max=Number($('distanceFilter')?.value||0);if(!max)return true;const d=walkEstimateData(l);return !!d&&d.miles<=max}
async function renderLists(){const mine=await localSnapshot();categoryOptions(mine);let ls=[...mine.landmarks],filter=$('categoryFilter').value,sub=$('subcategoryFilter').value;if(filter)ls=ls.filter(l=>(l.category||'Other')===filter);if(sub)ls=ls.filter(l=>(l.subcategory||'')===sub);ls=ls.filter(passesDistance);ls.sort((a,b)=>{const da=walkEstimateData(a)?.meters,db=walkEstimateData(b)?.meters;return Number.isFinite(da)&&Number.isFinite(db)?da-db:(a.name||'').localeCompare(b.name||'')});let partnerLs=[...(partnerSnapshot?.landmarks||[])];if(filter)partnerLs=partnerLs.filter(l=>(l.category||'Other')===filter);if(sub)partnerLs=partnerLs.filter(l=>(l.subcategory||'')===sub);partnerLs=partnerLs.filter(passesDistance);$('landmarkList').innerHTML=(ls.length?ls.map(l=>landmarkCard(l,mine.visits,false)).join(''):'<div class="empty">No landmarks match these filters.</div>')+(partnerSnapshot?.landmarks?.length?`<div class="panel-title"><h1>${esc(partner?.displayName||'Partner')} landmarks</h1></div>${partnerLs.length?partnerLs.map(l=>landmarkCard(l,partnerSnapshot.visits||[],true)).join(''):'<div class="empty">No partner landmarks match these filters.</div>'}`:'');document.querySelectorAll('[data-landmark-id]').forEach(el=>el.onclick=()=>openLandmarkById(el.dataset.landmarkId));renderMemories()}
function renderMemoriesLegacy(){const owner=$('memoryOwner').value;const data=owner==='partner'?partnerSnapshot:null;const name=owner==='partner'?(partner?.displayName||'Partner'):'My';if(owner==='partner'&&!data){$('statsGrid').innerHTML='<div class="window-card">No partner data loaded.</div>';$('walkList').innerHTML='';return}const d=data||{walks:[],landmarks:[],visits:[]};if(owner==='mine'){localSnapshot().then(x=>renderMemoryData(x,name))}else renderMemoryData(d,name)}
function renderMemoryData(d,name){const ws=[...(d.walks||[])],vs=d.visits||[],total=ws.reduce((a,w)=>a+Number(w.distance||0),0),longest=Math.max(0,...ws.map(w=>Number(w.distance||0)));$('statsGrid').innerHTML=[['Walks',ws.length],['Miles',mi(total)],['Longest',`${mi(longest)} mi`],['Landmark visits',vs.length]].map(([l,v])=>`<div class="window-card"><div class="stat">${v}</div><div class="muted">${l}</div></div>`).join('');$('walkHistoryTitle').textContent=`${name} recent walks`;ws.sort((a,b)=>Number(b.date||0)-Number(a.date||0));$('walkList').innerHTML=ws.length?ws.map(w=>`<div class="window-card clickable" data-walk-uid="${esc(w.uid)}" data-walk-owner="${$('memoryOwner').value}"><div class="walk-row"><div><b>${esc(w.title||'Walk')}</b><br>${mi(w.distance)} mi · ${ft(w.duration)}</div><div class="muted">${esc(formatDate(w.date))}<br>${(w.points||[]).length} GPS points</div></div></div>`).join(''):'<div class="empty">No saved walks yet.</div>';document.querySelectorAll('[data-walk-uid]').forEach(el=>el.onclick=()=>openWalk(el.dataset.walkUid,el.dataset.walkOwner))}
async function openWalkLegacy(walkUid,owner='mine'){const d=owner==='partner'?partnerSnapshot:await localSnapshot(),w=(d?.walks||[]).find(x=>x.uid===walkUid);if(!w)return;$('walkModalTitle').textContent=`${owner==='partner'?(partner?.displayName||'Partner')+': ':''}${w.title||'Walk'}`;$('walkMeta').textContent=`${mi(w.distance)} mi · ${ft(w.duration)} · ${formatDate(w.date)} · ${(w.points||[]).length} GPS points`;$('walkModal').classList.remove('hidden');setTimeout(()=>{if(!walkModalMap){walkModalMap=L.map('walkMap').setView([42.59,-72.60],13);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap contributors',maxZoom:19}).addTo(walkModalMap);walkModalLayer=L.layerGroup().addTo(walkModalMap)}walkModalLayer.clearLayers();walkModalMap.invalidateSize();const c=(w.points||[]).filter(p=>Number.isFinite(Number(p.lat))&&Number.isFinite(Number(p.lon))).map(p=>[+p.lat,+p.lon]);if(c.length){const line=L.polyline(c,{weight:5,color:owner==='partner'?safeColor(partner?.walkColor,'#777777'):safeColor(account?.walkColor,'#d00000')}).addTo(walkModalLayer);L.circleMarker(c[0],{radius:6}).bindTooltip('Start').addTo(walkModalLayer);if(c.length>1)L.circleMarker(c[c.length-1],{radius:6}).bindTooltip('End').addTo(walkModalLayer);walkModalMap.fitBounds(line.getBounds(),{padding:[24,24],maxZoom:18})}},60)}

function apiBase(){const custom=String(settings.apiBase||'').trim().replace(/\/$/,'');return custom||(location.protocol==='http:'||location.protocol==='https:'?location.origin:'')}function apiPath(p){const b=apiBase();if(!b)throw new Error('Set your Render server URL in Data first.');return b+p}
async function authFetch(path,opts={}){const h={...(opts.headers||{})};if(settings.token)h.authorization=`Bearer ${settings.token}`;const r=await fetch(apiPath(path),{...opts,headers:h,cache:'no-store'});let body={};try{body=await r.json()}catch{}if(!r.ok)throw Object.assign(new Error(body.error||`HTTP ${r.status}`),{status:r.status});return body}
function setCloudStatus(text,ok=false,error=false){const el=$('cloudStatus');el.textContent=text;el.classList.toggle('status-ok',ok);el.classList.toggle('status-error',error)}
async function signup(){try{const body=await fetch(apiPath('/api/auth/signup'),{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({displayName:$('signupDisplay').value,username:$('signupUser').value,password:$('signupPass').value,walkColor:$('signupColor').value})}).then(async r=>{const b=await r.json();if(!r.ok)throw new Error(b.error);return b});settings.token=body.token;saveSettings();account=body.user;await afterLogin()}catch(e){alert(e.message)}}
async function login(){try{const body=await fetch(apiPath('/api/auth/login'),{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({username:$('loginUser').value,password:$('loginPass').value})}).then(async r=>{const b=await r.json();if(!r.ok)throw new Error(b.error);return b});settings.token=body.token;saveSettings();account=body.user;await afterLogin()}catch(e){alert(e.message)}}
async function afterLogin(){try{const cloud=await authFetch('/api/snapshot');await mergeSnapshot(cloud.data);await loadAccount();await cloudPush();await refreshAll()}catch(e){if(e.status===401){delete settings.token;saveSettings()}alert(`Signed in, but sync had a problem: ${e.message}`)}updateAccountUI()}
async function logout(){try{await authFetch('/api/auth/logout',{method:'POST'})}catch{}delete settings.token;saveSettings();account=null;partner=null;partnerSnapshot=null;updateAccountUI();await refreshAll()}
async function loadAccount(){if(!settings.token){account=null;partner=null;partnerSnapshot=null;updateAccountUI();return}try{const m=await authFetch('/api/me');account=m.user;partner=m.partner;if(partner){try{const p=await authFetch('/api/partner-snapshot');partner=p.partner;partnerSnapshot=p.data}catch{partnerSnapshot=null}}else partnerSnapshot=null;updateAccountUI()}catch(e){if(e.status===401){delete settings.token;saveSettings();account=null;partner=null;partnerSnapshot=null;updateAccountUI()}else console.warn(e)}}
async function cloudPush(){if(!settings.token)return;setCloudStatus('SYNCING...');try{await authFetch('/api/snapshot',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({data:await localSnapshot()})});setCloudStatus(`SYNCED ${new Date().toLocaleTimeString()}`,true);await loadPartnerOnly()}catch(e){setCloudStatus(`SYNC FAILED: ${e.message}`,false,true)}}
async function cloudPull(){if(!settings.token)return;setCloudStatus('DOWNLOADING CLOUD DATA...');try{const c=await authFetch('/api/snapshot');await mergeSnapshot(c.data);await loadAccount();await refreshAll();await cloudPush()}catch(e){setCloudStatus(`SYNC FAILED: ${e.message}`,false,true)}}
async function loadPartnerOnly(){if(!partner)return;try{const p=await authFetch('/api/partner-snapshot');partner=p.partner;partnerSnapshot=p.data;await rebuildEtaProfile();await renderMap();await renderLists()}catch{partnerSnapshot=null;await rebuildEtaProfile()}}
function scheduleCloudSync(){if(!settings.token)return;clearTimeout(syncTimer);syncTimer=setTimeout(cloudPush,900)}
async function connectPartner(){try{await authFetch('/api/account/connect',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({code:$('partnerCode').value.trim()})});await loadAccount();await refreshAll()}catch(e){alert(e.message)}}
async function disconnectPartner(){if(!confirm('Disconnect your partner accounts? Your own walks will stay intact.'))return;try{await authFetch('/api/account/disconnect',{method:'POST'});await loadAccount();await refreshAll()}catch(e){alert(e.message)}}
async function newInvite(){try{const r=await authFetch('/api/account/new-invite',{method:'POST'});account.inviteCode=r.inviteCode;updateAccountUI()}catch(e){alert(e.message)}}
async function saveDisplayName(){try{await authFetch('/api/account/display-name',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({displayName:$('displayNameEdit').value})});await loadAccount()}catch(e){alert(e.message)}}
async function saveWalkColor(){try{await authFetch('/api/account/walk-color',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({walkColor:$('walkColorEdit').value})});await loadAccount();await refreshAll()}catch(e){alert(e.message)}}
function updateAccountUI(){const on=!!account;$('signedOutPanel').classList.toggle('hidden',on);$('signedInPanel').classList.toggle('hidden',!on);$('accountBadge').textContent=on?`${account.displayName}${partner?' ♥ '+partner.displayName:''}`:'OFFLINE MODE';if(!on)return;$('meName').textContent=account.displayName;$('meUsername').textContent=`@${account.username}`;$('displayNameEdit').value=account.displayName;$('walkColorEdit').value=safeColor(account.walkColor,'#d00000');$('inviteCode').textContent=account.inviteCode||'--------';$('partnerLinked').classList.toggle('hidden',!partner);$('partnerUnlinked').classList.toggle('hidden',!!partner);if(partner)$('partnerName').textContent=`♥ ${partner.displayName} (@${partner.username})`}

function downloadJSON(data,filename){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}async function exportFullLegacy(){downloadJSON({...await localSnapshot(),type:'full',exported:new Date().toISOString()},`walk-memory-full-${new Date().toISOString().slice(0,10)}.json`)}async function exportWalksLegacy(){downloadJSON({version:4,type:'walks',walks:await all('walks')},`walk-memory-walks-${new Date().toISOString().slice(0,10)}.json`)}async function exportLandmarks(){const ls=await all('landmarks'),ids=new Set(ls.map(l=>l.uid)),vs=(await all('visits')).filter(v=>ids.has(v.landmarkUid));downloadJSON({version:4,type:'landmarks',landmarks:ls,visits:vs},`walk-memory-landmarks-${new Date().toISOString().slice(0,10)}.json`)}
async function upsertImported(name,record){const x={...record};delete x.id;if(!x.uid)x.uid=uid();x.updatedAt=x.updatedAt||now();const ex=(await all(name)).find(y=>y.uid===x.uid);if(ex)x.id=ex.id;return put(name,x)}async function importFileLegacy(file,kind){if(!file)return;try{const d=JSON.parse(await file.text());if(kind==='walks'){for(const x of d.walks||[])await upsertImported('walks',x)}else if(kind==='landmarks'){for(const x of d.landmarks||[])await upsertImported('landmarks',x);for(const x of d.visits||[])await upsertImported('visits',x)}else{for(const x of d.walks||[])await upsertImported('walks',x);for(const x of d.landmarks||[])await upsertImported('landmarks',x);for(const x of d.visits||[])await upsertImported('visits',x)}await migrateData();await refreshAll();scheduleCloudSync();alert('Import complete.')}catch(e){alert(`Could not import: ${e.message}`)}}async function wipeLocalLegacy(){if(!confirm('Delete ALL local walks, landmarks, visits, and photos from this device?'))return;for(const s of ['walks','landmarks','visits'])await clearStore(s);await refreshAll();scheduleCloudSync()}
async function refreshAllLegacy(){await renderLists();await renderMap()}

function showPageLegacy(page){document.querySelectorAll('.page').forEach(x=>x.classList.remove('active'));$(page).classList.add('active');document.querySelectorAll('.tabs button').forEach(x=>x.classList.toggle('active-tab',x.dataset.page===page));if(page==='map')setTimeout(()=>map?.invalidateSize(),50);if(page==='account')loadAccount();if(page==='stats')renderMemories()}
function bindUILegacy(){document.querySelectorAll('.tabs button').forEach(b=>b.onclick=()=>showPage(b.dataset.page));document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>closeModal(b.dataset.close));document.querySelectorAll('.modal').forEach(m=>m.addEventListener('click',e=>{if(e.target===m)closeModal(m.id)}));$('start').onclick=startTracking;$('stop').onclick=stopTracking;$('locate').onclick=()=>locateMe(false);$('refreshLandmarkLocation').onclick=()=>locateMe(true);$('addLandmark').onclick=openNewLandmark;$('lmPhotos').onchange=addSelectedPhotos;$('lmGalleryInput').onchange=addSelectedPhotos;$('lmTakePhoto').onclick=()=>nativeCameraAvailable()?addLandmarkPhotoFromNative('camera'):$('lmPhotos').click();$('lmChoosePhoto').onclick=()=>nativeCameraAvailable()?addLandmarkPhotoFromNative('gallery'):$('lmGalleryInput').click();$('lmForm').onsubmit=saveLandmark;$('deleteLandmark').onclick=deleteCurrentLandmark;$('categoryFilter').onchange=()=>{subcategoryOptions({landmarks:[]});renderLists()};$('subcategoryFilter').onchange=renderLists;$('distanceFilter').onchange=()=>lastKnownLocation?renderLists():locateMe(true);$('mapOwner').onchange=renderMap;$('memoryOwner').onchange=renderMemories;$('signupBtn').onclick=signup;$('loginBtn').onclick=login;$('logoutBtn').onclick=logout;$('connectPartner').onclick=connectPartner;$('disconnectPartner').onclick=disconnectPartner;$('newInvite').onclick=newInvite;$('saveDisplayName').onclick=saveDisplayName;$('saveWalkColor').onclick=saveWalkColor;$('copyInvite').onclick=async()=>{if(!account?.inviteCode)return;try{await navigator.clipboard.writeText(account.inviteCode);alert('Invite code copied.')}catch{prompt('Copy code:',account.inviteCode)}};$('syncNow').onclick=cloudPull;$('apiBase').value=settings.apiBase||'';$('apiBase').onchange=()=>{settings.apiBase=$('apiBase').value.trim();saveSettings()};$('exportFull').onclick=exportFull;$('exportWalks').onclick=exportWalks;$('exportLandmarks').onclick=exportLandmarks;$('importFull').onchange=e=>importFile(e.target.files[0],'full');$('importWalks').onchange=e=>importFile(e.target.files[0],'walks');$('importLandmarks').onchange=e=>importFile(e.target.files[0],'landmarks');$('wipe').onclick=wipeLocal}

/* ===== Nights v6 enhancements ===== */
function timeBucket(ts=Date.now()){const h=new Date(ts).getHours();return h<6?'night':h<11?'morning':h<17?'day':h<22?'evening':'night'}
function distanceBucket(m){return m<1609.344?'short':m<4828?'medium':'long'}
function activityLabel(w){return (w?.activity||'walk')==='drive'?'Drive':'Walk'}
function elevationStats(w){const ps=(w?.points||[]).filter(p=>Number.isFinite(Number(p.altitude)));let gain=0,loss=0;for(let i=1;i<ps.length;i++){const dz=Number(ps[i].altitude)-Number(ps[i-1].altitude);if(Math.abs(dz)<1)continue;if(dz>0)gain+=dz;else loss-=dz}return{gain,loss}}
async function rebuildEtaProfile(){const own=(await all('walks')).filter(w=>(w.activity||'walk')==='walk'),partnerWalks=(partnerSnapshot?.walks||[]).filter(w=>(w.activity||'walk')==='walk'),seen=new Set(),combined=[];for(const w of [...own,...partnerWalks]){const key=w.uid||`${w.date}-${w.distance}-${w.duration}`;if(seen.has(key))continue;seen.add(key);if(Number(w.distance)>100&&Number(w.duration)>60000)combined.push(w)}let totalD=0,totalT=0;const tGroups={},dGroups={},route=[];let gain=0,valid=0;for(const w of combined){const d=Number(w.distance),sec=Number(w.duration)/1000,speed=d/sec;if(speed<.45||speed>2.8)continue;valid++;totalD+=d;totalT+=sec;(tGroups[timeBucket(w.date)]||=[]).push(speed);(dGroups[distanceBucket(d)]||=[]).push(speed);const ps=w.points||[];if(ps.length>1){const direct=dist(ps[0],ps[ps.length-1]);if(direct>150)route.push(Math.min(2.2,Math.max(1.05,d/direct)))}gain+=elevationStats(w).gain}const avg=a=>a?.length?a.reduce((x,y)=>x+y,0)/a.length:null;etaProfile={baseSpeed:totalT?Math.min(2.3,Math.max(.65,totalD/totalT)):1.4,routeFactor:route.length?Math.min(1.7,Math.max(1.1,avg(route))):1.25,timeSpeeds:Object.fromEntries(Object.entries(tGroups).map(([k,v])=>[k,avg(v)])),distanceSpeeds:Object.fromEntries(Object.entries(dGroups).map(([k,v])=>[k,avg(v)])),hilliness:totalD?gain/totalD:0,sampleCount:valid};if($('etaLearning')){const shared=partnerWalks.length?` · shared with ${partner?.displayName||'partner'} history`:'';$('etaLearning').textContent=valid?`ETA model: ${valid} combined recorded walks${shared}`:'ETA model: learning from your walks'}}
function walkEstimateData(l){if(!lastKnownLocation)return null;const direct=dist(lastKnownLocation,l),estimatedMeters=direct*etaProfile.routeFactor;const tb=timeBucket(),db=distanceBucket(estimatedMeters);let speed=etaProfile.baseSpeed;const ts=etaProfile.timeSpeeds[tb],ds=etaProfile.distanceSpeeds[db];if(ts)speed=(speed*2+ts)/3;if(ds)speed=(speed*2+ds)/3;const localGrade=Math.abs(Number(currentSlopePercent||0))/100;const learnedHill=Math.min(.12,etaProfile.hilliness);const terrainPenalty=1+Math.min(.28,localGrade*.9+learnedHill*.8);const mins=Math.max(1,Math.round((estimatedMeters/Math.max(.55,speed))*terrainPenalty/60));const confidence=etaProfile.sampleCount>=8?'high':etaProfile.sampleCount>=3?'learning':'starter';return{meters:estimatedMeters,miles:estimatedMeters/1609.344,mins,text:`~${mins} min · ${mi(estimatedMeters)} mi · ${confidence} ETA`,details:`Personal pace + ${tb} pace + distance + learned terrain/elevation`}}
async function historicalSlopeNear(loc){try{const ws=(await all('walks')).filter(w=>(w.activity||'walk')==='walk');let best=null,bestD=Infinity;for(const w of ws){const ps=w.points||[];for(let i=1;i<ps.length;i++){const a=ps[i-1],b=ps[i];if(!Number.isFinite(Number(a.altitude))||!Number.isFinite(Number(b.altitude)))continue;const mid={lat:(Number(a.lat)+Number(b.lat))/2,lon:(Number(a.lon)+Number(b.lon))/2},near=dist(loc,mid),run=dist(a,b);if(near<bestD&&near<120&&run>=12&&run<=150){const grade=(Number(b.altitude)-Number(a.altitude))/run*100;if(Math.abs(grade)<=40){bestD=near;best=grade}}}}return best}catch{return null}}
function updateTerrainReadout(){if($('mapElevation'))$('mapElevation').textContent=currentElevation==null?'Elevation: —':`Elevation: ${Math.round(currentElevation*3.28084)} ft`;if($('mapSlope')){if(currentSlopePercent==null){$('mapSlope').textContent='Slope: —';$('mapSlope').className=''}else{const a=Math.abs(currentSlopePercent),label=a<2?'flat':a<5?'gentle':a<9?'moderate':a<15?'steep':'very steep',dir=currentSlopePercent>1?'uphill':currentSlopePercent<-1?'downhill':'level';$('mapSlope').textContent=`Slope: ${Math.abs(currentSlopePercent).toFixed(1)}% ${dir} · ${label}`;$('mapSlope').className=a>=9?'slope-steep':currentSlopePercent<-2?'slope-down':''}}}
function updateSlope(p){if(Number.isFinite(p.altitude)){currentElevation=p.altitude;slopeHistory.push(p);slopeHistory=slopeHistory.slice(-8);let base=null;for(const q of slopeHistory){if(dist(q,p)>=18){base=q;break}}if(base){const horizontal=dist(base,p),vertical=p.altitude-base.altitude;if(horizontal>=18&&Math.abs(vertical)<100)currentSlopePercent=Math.max(-45,Math.min(45,vertical/horizontal*100))}}updateTerrainReadout()}
async function localSnapshot(){return{version:6,walks:await all('walks'),landmarks:await all('landmarks'),visits:await all('visits'),photos:await all('photos')}}
async function mergeSnapshot(snap){if(!snap)return;for(const name of ['walks','landmarks','visits','photos'])for(const original of snap[name]||[]){const x={...original};delete x.id;if(!x.uid)x.uid=uid();const existing=(await all(name)).find(y=>y.uid===x.uid);if(existing)x.id=existing.id;await put(name,x)}await migrateData();await rebuildEtaProfile()}
async function acceptPosition(coords,timestamp=now()){const accuracy=Number(coords.accuracy??9999);$('gpsDetail').textContent=Number.isFinite(accuracy)?`GPS accuracy: ±${Math.round(accuracy)} m`:'GPS active';if(accuracy>100){$('state').textContent=`WAITING FOR BETTER GPS ±${Math.round(accuracy)}m`;return}const p={lat:Number(coords.latitude),lon:Number(coords.longitude),t:Number(timestamp||now()),accuracy,altitude:coords.altitude==null?null:Number(coords.altitude),speed:coords.speed==null?null:Number(coords.speed)};if(!Number.isFinite(p.lat)||!Number.isFinite(p.lon))return;lastKnownLocation={lat:p.lat,lon:p.lon};updateSlope(p);if(lastPoint){const d=dist(lastPoint,p),sec=Math.max(.001,(p.t-lastPoint.t)/1000),speed=d/sec,minMove=currentActivityType==='drive'?Math.max(4,Math.min(15,accuracy*.12)):Math.max(2,Math.min(8,(accuracy+Number(lastPoint.accuracy||accuracy))*.06)),maxSpeed=currentActivityType==='drive'?75:12;if(d<minMove)return;if(speed>maxSpeed&&(p.speed==null||p.speed>maxSpeed))return;meters+=d}points.push(p);lastPoint=p;$('state').textContent=`TRACKING ${currentActivityType.toUpperCase()}`;renderLive();tick();await checkLandmarks(p,currentWalkUid);renderPhotoTab()}
function tick(){const d=startAt?now()-startAt:0;$('duration').textContent=ft(d);$('distance').textContent=`${mi(meters)} mi`;if(currentActivityType==='drive')$('pace').textContent=d>0?`${((meters/1609.344)/(d/3600000)).toFixed(1)} mph`:'—';else $('pace').textContent=meters>0?`${((d/60000)/(meters/1609.344)).toFixed(1)} min/mi`:'—'}
async function startTracking(){if(joinedPartnerActivity)return alert('Leave partner sync before starting your own activity.');currentActivityType=$('activityMode')?.value||'walk';meters=0;points=[];lastPoint=null;slopeHistory=[];startAt=now();currentWalkUid=uid();$('activityMode').disabled=true;$('start').disabled=true;$('stop').disabled=false;$('state').textContent='STARTING GPS';timer=setInterval(tick,1000);renderPhotoTab();sharedHostActive=false;if($('sharePartnerActivity')?.checked&&settings.token&&partner){try{await authFetch('/api/shared-activity/start',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({activityUid:currentWalkUid,type:currentActivityType})});sharedHostActive=true;updateSharedActivityUI('Sharing live activity with partner.')}catch(e){updateSharedActivityUI(`Partner sync unavailable: ${e.message}`,true)}}if(nativeBridgeAvailable()){try{$('backgroundNote').textContent=`Native background GPS active for this ${currentActivityType}. Keep location Allow all the time, battery Unrestricted, and Remove permissions if unused off.`;$('backgroundNote').classList.remove('hidden');nativeWatchId=await window.WalkMemoryNative.start(loc=>acceptPosition({latitude:loc.latitude,longitude:loc.longitude,accuracy:loc.accuracy,altitude:loc.altitude,speed:loc.speed},loc.time),err=>{$('state').textContent=`GPS ERROR: ${err?.message||err}`});return}catch{$('backgroundNote').textContent='Native GPS failed; falling back to browser GPS.';$('backgroundNote').classList.remove('hidden')}}if(!navigator.geolocation){resetTrackingUI();return alert('GPS unavailable.')}watchId=navigator.geolocation.watchPosition(p=>acceptPosition(p.coords,p.timestamp),e=>{$('state').textContent=`GPS: ${e.message}`},{enableHighAccuracy:true,maximumAge:0,timeout:20000})}
async function stopTracking(){if(watchId!==null){navigator.geolocation.clearWatch(watchId);watchId=null}if(nativeWatchId!==null&&window.WalkMemoryNative?.stop){try{await window.WalkMemoryNative.stop(nativeWatchId)}catch{}nativeWatchId=null}clearInterval(timer);timer=null;let contributed=[];if(sharedHostActive&&settings.token){try{const r=await authFetch('/api/shared-activity/finish',{method:'POST'});contributed=r.photos||[]}catch{}sharedHostActive=false}if(points.length<2){for(const ph of await all('photos'))if(ph.activityUid===currentWalkUid)await remove('photos',ph.id);resetTrackingUI();updateSharedActivityUI();return alert('Not enough accurate GPS points to save this activity.')}for(const ph of contributed){const x={...ph};delete x.id;x.activityUid=currentWalkUid;x.uid=ph.uid||uid();x.updatedAt=now();await put('photos',x)}const kind=currentActivityType==='drive'?'Drive':'Walk',title=prompt(`Name this ${kind.toLowerCase()}:`,`${kind} ${new Date(startAt).toLocaleDateString()}`)||kind;const es=elevationStats({points});await put('walks',{uid:currentWalkUid,date:startAt,duration:now()-startAt,distance:meters,title,activity:currentActivityType,points:[...points],elevationGain:es.gain,elevationLoss:es.loss,updatedAt:now()});$('state').textContent='SAVED';resetTrackingUI();updateSharedActivityUI();await rebuildEtaProfile();await refreshAll();scheduleCloudSync()}
function resetTrackingUI(){$('activityMode').disabled=false;$('start').disabled=false;$('stop').disabled=true;$('distance').textContent='0.00 mi';$('duration').textContent='00:00:00';$('pace').textContent='—';points=[];lastPoint=null;meters=0;startAt=0;currentWalkUid=null;if(liveLine&&map){map.removeLayer(liveLine);liveLine=null}renderPhotoTab()}
async function locateMe(refresh=false){if(!navigator.geolocation)return alert('GPS unavailable.');navigator.geolocation.getCurrentPosition(async p=>{lastKnownLocation={lat:p.coords.latitude,lon:p.coords.longitude};if(Number.isFinite(p.coords.altitude))currentElevation=p.coords.altitude;if(currentSlopePercent==null){const learned=await historicalSlopeNear(lastKnownLocation);if(learned!=null)currentSlopePercent=learned}updateTerrainReadout();map?.setView([p.coords.latitude,p.coords.longitude],16);renderMap();if(refresh)renderLists()},e=>alert(e.message),{enableHighAccuracy:true,maximumAge:0,timeout:15000})}
async function storeActivityPhotoData(data){if(!data)return;let loc=lastPoint||lastKnownLocation;if(!loc&&navigator.geolocation)try{loc=await new Promise((res,rej)=>navigator.geolocation.getCurrentPosition(p=>res({lat:p.coords.latitude,lon:p.coords.longitude,altitude:p.coords.altitude}),rej,{enableHighAccuracy:true,timeout:10000}))}catch{}if(!loc)return alert('Waiting for a GPS location. Try again in a moment.');if(joinedPartnerActivity){try{updateSharedActivityUI('Uploading photo to shared activity...');await authFetch('/api/shared-activity/photo',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({image:data,date:now(),lat:Number(loc.lat),lon:Number(loc.lon),altitude:loc.altitude==null?null:Number(loc.altitude)})});updateSharedActivityUI('Photo added to partner activity.');await renderPhotoTab();return}catch(e){updateSharedActivityUI('Photo upload failed.',true);return alert(`Could not add photo to partner activity: ${e.message}`)}}if(!currentWalkUid)return alert('Start a walk or drive first, or sync with your partner.');await put('photos',{uid:uid(),activityUid:currentWalkUid,date:now(),lat:Number(loc.lat),lon:Number(loc.lon),altitude:loc.altitude==null?null:Number(loc.altitude),image:data,updatedAt:now()});await renderPhotoTab();scheduleCloudSync()}
async function addActivityPhoto(file){if(!file?.type?.startsWith('image/'))return;const data=await readPhoto(file);await storeActivityPhotoData(data)}
async function captureActivityPhoto(source='camera'){if(photoBusy)return;if(!currentWalkUid&&!joinedPartnerActivity)return alert('Start a walk or drive first, or sync with your partner.');photoBusy=true;try{if(nativeCameraAvailable()){const raw=source==='gallery'?await window.WalkMemoryNative.choosePhoto():await window.WalkMemoryNative.takePhoto();const data=await normalizeNativePhoto(raw);if(data)await storeActivityPhotoData(data)}else{const id=source==='gallery'?'activityGalleryInput':'activityPhotoInput';$(id)?.click()}}catch(e){if(!/cancel/i.test(String(e?.message||e)))alert(`Camera: ${e?.message||e}`)}finally{photoBusy=false}}
async function renderPhotoTab(){if(!$('photoActivityStatus'))return;if(joinedPartnerActivity){$('photoActivityStatus').textContent=`SYNCED TO ${joinedPartnerActivity.host?.displayName||'PARTNER'} · photos attach to their ${String(joinedPartnerActivity.type||'activity').toUpperCase()}`;$('currentActivityPhotos').innerHTML='<div class="muted">Your photos will be attached to your partner’s shared activity and appear in its Memory after they save it.</div>';return}const active=!!currentWalkUid;$('photoActivityStatus').textContent=active?`${currentActivityType.toUpperCase()} ACTIVE · photos attach automatically`:'START A WALK OR DRIVE, OR SYNC WITH YOUR PARTNER';const ps=active?(await all('photos')).filter(p=>p.activityUid===currentWalkUid):[];$('currentActivityPhotos').innerHTML=ps.length?ps.sort((a,b)=>a.date-b.date).map(p=>`<div class="activity-shot"><img src="${safeImageSrc(p.image)}"><small>${esc(new Date(p.date).toLocaleTimeString())}</small></div>`).join(''):'<div class="muted">No photos on the current activity yet.</div>'}
async function renderMemories(){const owner=$('memoryOwner').value,d=owner==='partner'?partnerSnapshot:await localSnapshot(),ws=d?.walks||[];const walks=ws.filter(w=>(w.activity||'walk')==='walk'),drives=ws.filter(w=>w.activity==='drive'),total=walks.reduce((s,w)=>s+Number(w.distance||0),0);$('statsGrid').innerHTML=`<div class="window-card"><div class="stat">${walks.length}</div><small>walks</small></div><div class="window-card"><div class="stat">${drives.length}</div><small>drives</small></div><div class="window-card"><div class="stat">${mi(total)}</div><small>walk miles</small></div><div class="window-card"><div class="stat">${(d?.landmarks||[]).length}</div><small>landmarks</small></div>`;$('walkHistoryTitle').textContent=owner==='partner'?`${partner?.displayName||'Partner'} activities`:'Recent activities';$('walkList').innerHTML=ws.length?[...ws].sort((a,b)=>b.date-a.date).map(w=>`<div class="window-card clickable walk-row" data-walk-uid="${esc(w.uid)}" data-walk-owner="${owner}"><div><b>${esc(w.title||activityLabel(w))}</b><span class="activity-type ${w.activity==='drive'?'drive-type':''}">${activityLabel(w).toUpperCase()}</span><div>${mi(w.distance)} mi · ${ft(w.duration)}</div></div><div class="muted">${esc(formatDate(w.date))}<br>${(w.points||[]).length} GPS points</div></div>`).join(''):'<div class="empty">No saved activities yet.</div>';document.querySelectorAll('[data-walk-uid]').forEach(el=>el.onclick=()=>openWalk(el.dataset.walkUid,el.dataset.walkOwner))}
async function openWalk(walkUid,owner='mine'){const d=owner==='partner'?partnerSnapshot:await localSnapshot(),w=(d?.walks||[]).find(x=>x.uid===walkUid);if(!w)return;const visits=(d?.visits||[]).filter(v=>v.walkUid===walkUid),landmarks=d?.landmarks||[],visited=[...new Map(visits.map(v=>{const l=landmarks.find(x=>x.uid===v.landmarkUid);return l?[l.uid,l]:null}).filter(Boolean)).values()],photos=(d?.photos||[]).filter(p=>p.activityUid===walkUid).sort((a,b)=>a.date-b.date),es=elevationStats(w);$('walkModalTitle').textContent=`${owner==='partner'?(partner?.displayName||'Partner')+': ':''}${w.title||activityLabel(w)}`;$('walkMeta').textContent=`${activityLabel(w)} · ${mi(w.distance)} mi · ${ft(w.duration)} · ${formatDate(w.date)} · ${(w.points||[]).length} GPS points · ↑${Math.round(es.gain*3.28084)} ft`;$('walkVisitSummary').innerHTML=`<b>Landmarks visited (${visited.length})</b><div>${visited.length?visited.map(l=>`★ ${esc(l.name)}`).join(' · '):'None recorded on this activity.'}</div>`;$('walkPhotoGallery').innerHTML=photos.length?photos.map(p=>`<div class="activity-shot"><img src="${safeImageSrc(p.image)}"><small>${esc(new Date(p.date).toLocaleTimeString())}</small></div>`).join(''):'<div class="muted">No photos on this activity.</div>';$('walkModal').classList.remove('hidden');setTimeout(()=>{if(!walkModalMap){walkModalMap=L.map('walkMap').setView([42.59,-72.60],13);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap contributors',maxZoom:19}).addTo(walkModalMap);walkModalLayer=L.layerGroup().addTo(walkModalMap)}walkModalLayer.clearLayers();walkModalMap.invalidateSize();const c=(w.points||[]).filter(p=>Number.isFinite(Number(p.lat))&&Number.isFinite(Number(p.lon))).map(p=>[+p.lat,+p.lon]);if(c.length){const line=L.polyline(c,{weight:5,color:owner==='partner'?safeColor(partner?.walkColor,'#777777'):safeColor(account?.walkColor,'#d00000')}).addTo(walkModalLayer);L.circleMarker(c[0],{radius:6}).bindTooltip('Start').addTo(walkModalLayer);if(c.length>1)L.circleMarker(c[c.length-1],{radius:6}).bindTooltip('End').addTo(walkModalLayer);for(const l of visited)L.marker([l.lat,l.lon],{icon:landmarkMarker(l,owner==='partner')}).bindPopup(`<b>${esc(l.name)}</b><br>Visited on this ${activityLabel(w).toLowerCase()}`).addTo(walkModalLayer);for(const ph of photos)L.circleMarker([ph.lat,ph.lon],{radius:7,color:'#ffcc00',fillOpacity:.9}).bindPopup(`<img src="${safeImageSrc(ph.image)}" style="width:180px;max-width:100%;border:2px solid #555"><br>${esc(new Date(ph.date).toLocaleString())}`).addTo(walkModalLayer);walkModalMap.fitBounds(line.getBounds(),{padding:[24,24],maxZoom:18})}},60)}
async function exportFull(){downloadJSON({...await localSnapshot(),type:'full',exported:new Date().toISOString()},`nights-v6-full-${new Date().toISOString().slice(0,10)}.json`)}
async function exportWalks(){const walks=await all('walks'),ids=new Set(walks.map(w=>w.uid)),photos=(await all('photos')).filter(p=>ids.has(p.activityUid));downloadJSON({version:6,type:'walks',walks,photos},`nights-v6-activities-${new Date().toISOString().slice(0,10)}.json`)}
async function importFile(file,kind){if(!file)return;try{const d=JSON.parse(await file.text());if(kind==='walks'){for(const x of d.walks||[])await upsertImported('walks',x);for(const x of d.photos||[])await upsertImported('photos',x)}else if(kind==='landmarks'){for(const x of d.landmarks||[])await upsertImported('landmarks',x);for(const x of d.visits||[])await upsertImported('visits',x)}else{for(const n of ['walks','landmarks','visits','photos'])for(const x of d[n]||[])await upsertImported(n,x)}await migrateData();await rebuildEtaProfile();await refreshAll();scheduleCloudSync();alert('Import complete.')}catch(e){alert(`Could not import: ${e.message}`)}}
async function wipeLocal(){if(!confirm('Delete ALL local walks, drives, landmarks, visits, and activity photos from this device?'))return;for(const s of ['walks','landmarks','visits','photos'])await clearStore(s);await rebuildEtaProfile();await refreshAll();scheduleCloudSync()}

function applyAppSettings(){const scale=Number(settings.guiScale||1);document.body.style.zoom=String(Math.max(.7,Math.min(1.5,scale)));document.body.classList.toggle('compact-ui',!!settings.compactUI)}
function loadSettingsUI(){if(!$('guiScale'))return;$('guiScale').value=String(settings.guiScale||1);$('compactUI').checked=!!settings.compactUI;$('showPhotoMarkers').checked=settings.showPhotoMarkers!==false;$('autoCenterTracking').checked=!!settings.autoCenterTracking;$('defaultMapOwner').value=settings.defaultMapOwner||'mine'}
async function saveSettingsFromUI(){settings.guiScale=Number($('guiScale').value||1);settings.compactUI=$('compactUI').checked;settings.showPhotoMarkers=$('showPhotoMarkers').checked;settings.autoCenterTracking=$('autoCenterTracking').checked;settings.defaultMapOwner=$('defaultMapOwner').value;saveSettings();applyAppSettings();if($('mapOwner'))$('mapOwner').value=settings.defaultMapOwner;await renderMap();setTimeout(()=>map?.invalidateSize(),50)}
async function resetPasswordWithPartnerCode(){const username=$('resetUser').value.trim(),partnerCode=$('resetPartnerCode').value.trim(),newPassword=$('resetNewPass').value;if(!username||!partnerCode||newPassword.length<8)return alert('Enter your username, partner code, and a new password of at least 8 characters.');try{const r=await fetch(apiPath('/api/auth/reset-with-partner-code'),{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({username,partnerCode,newPassword})});let b={};try{b=await r.json()}catch{}if(!r.ok)throw new Error(b.error||`HTTP ${r.status}`);alert('Password reset. Sign in with the new password.');$('loginUser').value=username;$('loginPass').value=''}catch(e){alert(e.message)}}
function updateSharedActivityUI(text='',error=false){const el=$('sharedActivityStatus');if(!el)return;if(text)el.textContent=text;else if(joinedPartnerActivity)el.textContent=`Synced to ${joinedPartnerActivity.host?.displayName||'partner'} ${joinedPartnerActivity.type||'activity'}.`;else if(sharedHostActive)el.textContent='Sharing live activity with partner.';else el.textContent='Not synced with a partner activity.';el.style.color=error?'#8b0000':'';$('joinPartnerActivity')?.classList.toggle('hidden',!!joinedPartnerActivity);$('leavePartnerActivity')?.classList.toggle('hidden',!joinedPartnerActivity)}
async function joinPartnerActivity(){if(!settings.token||!partner)return alert('Sign in and link your partner first.');if(currentWalkUid)return alert('Stop your current activity before syncing with your partner.');try{const r=await authFetch('/api/shared-activity');if(!r.active||r.role!=='partner')return alert('Your partner is not currently sharing a walk or drive.');joinedPartnerActivity=r;$('start').disabled=true;$('activityMode').disabled=true;updateSharedActivityUI();renderPhotoTab()}catch(e){alert(e.message)}}
function leavePartnerActivity(){joinedPartnerActivity=null;$('start').disabled=false;$('activityMode').disabled=false;updateSharedActivityUI();renderPhotoTab()}
async function pollSharedActivity(){if(!settings.token||!partner)return;if(joinedPartnerActivity){try{const r=await authFetch('/api/shared-activity');if(!r.active||r.role!=='partner')leavePartnerActivity();else{joinedPartnerActivity=r;updateSharedActivityUI()}}catch{}}}

async function refreshAll(){await rebuildEtaProfile();await renderLists();await renderMap();await renderPhotoTab()}
function showPage(page){document.querySelectorAll('.page').forEach(x=>x.classList.remove('active'));$(page).classList.add('active');document.querySelectorAll('.tabs button').forEach(x=>x.classList.toggle('active-tab',x.dataset.page===page));if(page==='map')setTimeout(()=>map?.invalidateSize(),50);if(page==='account')loadAccount();if(page==='stats')renderMemories();if(page==='photos')renderPhotoTab();if(page==='settings')loadSettingsUI()}
function bindUI(){document.querySelectorAll('.tabs button').forEach(b=>b.onclick=()=>showPage(b.dataset.page));document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>closeModal(b.dataset.close));document.querySelectorAll('.modal').forEach(m=>m.addEventListener('click',e=>{if(e.target===m)closeModal(m.id)}));$('start').onclick=startTracking;$('stop').onclick=stopTracking;$('joinPartnerActivity').onclick=joinPartnerActivity;$('leavePartnerActivity').onclick=leavePartnerActivity;$('locate').onclick=()=>locateMe(false);$('refreshLandmarkLocation').onclick=()=>locateMe(true);$('addLandmark').onclick=openNewLandmark;$('lmPhotos').onchange=addSelectedPhotos;$('lmGalleryInput').onchange=addSelectedPhotos;$('lmTakePhoto').onclick=()=>nativeCameraAvailable()?addLandmarkPhotoFromNative('camera'):$('lmPhotos').click();$('lmChoosePhoto').onclick=()=>nativeCameraAvailable()?addLandmarkPhotoFromNative('gallery'):$('lmGalleryInput').click();$('lmForm').onsubmit=saveLandmark;$('deleteLandmark').onclick=deleteCurrentLandmark;$('categoryFilter').onchange=()=>{subcategoryOptions({landmarks:[]});renderLists()};$('subcategoryFilter').onchange=renderLists;$('distanceFilter').onchange=()=>lastKnownLocation?renderLists():locateMe(true);$('mapOwner').onchange=()=>{settings.defaultMapOwner=$('mapOwner').value;saveSettings();renderMap()};$('memoryOwner').onchange=renderMemories;$('activityPhotoInput').onchange=async e=>{const f=e.target.files?.[0];e.target.value='';if(f)try{await addActivityPhoto(f)}catch(err){alert(err.message)}};$('activityGalleryInput').onchange=async e=>{const f=e.target.files?.[0];e.target.value='';if(f)try{await addActivityPhoto(f)}catch(err){alert(err.message)}};$('activityTakePhoto').onclick=()=>captureActivityPhoto('camera');$('activityChoosePhoto').onclick=()=>captureActivityPhoto('gallery');$('signupBtn').onclick=signup;$('loginBtn').onclick=login;$('resetPasswordBtn').onclick=resetPasswordWithPartnerCode;$('logoutBtn').onclick=logout;$('connectPartner').onclick=connectPartner;$('disconnectPartner').onclick=disconnectPartner;$('newInvite').onclick=newInvite;$('saveDisplayName').onclick=saveDisplayName;$('saveWalkColor').onclick=saveWalkColor;$('copyInvite').onclick=async()=>{if(!account?.inviteCode)return;try{await navigator.clipboard.writeText(account.inviteCode);alert('Invite code copied.')}catch{prompt('Copy code:',account.inviteCode)}};$('syncNow').onclick=cloudPull;$('apiBase').value=settings.apiBase||'';$('apiBase').onchange=()=>{settings.apiBase=$('apiBase').value.trim();saveSettings()};$('exportFull').onclick=exportFull;$('exportWalks').onclick=exportWalks;$('exportLandmarks').onclick=exportLandmarks;$('importFull').onchange=e=>importFile(e.target.files[0],'full');$('importWalks').onchange=e=>importFile(e.target.files[0],'walks');$('importLandmarks').onchange=e=>importFile(e.target.files[0],'landmarks');$('wipe').onclick=wipeLocal;['guiScale','compactUI','showPhotoMarkers','autoCenterTracking','defaultMapOwner'].forEach(id=>$(id)?.addEventListener('change',saveSettingsFromUI))}

async function boot(){applyAppSettings();bindUI();await openDB();await migrateData();await initMap();await loadAccount();await renderLists();if(settings.token){await cloudPull().catch(()=>{});setInterval(()=>loadPartnerOnly(),45000);setInterval(()=>pollSharedActivity(),12000)}if('serviceWorker'in navigator&&(location.protocol==='http:'||location.protocol==='https:'))navigator.serviceWorker.register('./sw.js').catch(()=>{})}
boot().catch(e=>{console.error(e);alert(`Nights failed to start: ${e.message}`)})